using System;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        var thresholdVec = Vector256.Create(threshold);
        var oneVec = Vector256.Create(1);

        ref int start = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int vectorEnd = data.Length - Vector256<int>.Count;

        while (i <= vectorEnd)
        {
            var vec = Vector256.LoadUnsafe(ref start, (nuint)i);
            // CompareGreaterThan produces -1 (all bits set) for true, 0 for false.
            // Subtracting -1 is equivalent to adding 1 for matching lanes.
            var mask = Vector256.GreaterThan(vec, thresholdVec);
            vec -= mask;
            vec.StoreUnsafe(ref start, (nuint)i);
            i += Vector256<int>.Count;
        }

        for (; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

